-- build/erp/glassbowl_data.db patch (spec §46.1, F12): the posting db needs C_Currency.StdPrecision to convert a document into a schema of another currency
-- (FactLine.convert → MConversionRate.convert rounds HALF_UP to the target currency StdPrecision, MConversionRate.java:126-147). Values = the SQLite seed ad_seed_fullwidth.db
-- (SQLite's own dictionary), not invented. Idempotent; never deletes. Apply through a loader that runs it once per db copy (open item: no ERP-host loader yet).
CREATE TABLE IF NOT EXISTS c_currency(c_currency_id INT, iso_code TEXT, stdprecision INT);

-- 2026-10-10 (spec §56, F15): C_AcctSchema_Element (element type + IsBalanced) — Fact.balanceSegments posts intercompany Due-To/From only when the Organization element is balanced.
CREATE TABLE IF NOT EXISTS c_acctschema_element(c_acctschema_element_id INT, c_acctschema_id INT, elementtype TEXT, isbalanced TEXT);

-- 2026-10-10 (spec §57, F16): Doc_AllocationHdr posts in the allocation header's currency; the posting db's c_allocationhdr lacks the column.
-- ALTER statements must go through a guarded loader (dict_diff.applyPatch skips an ADD COLUMN that PRAGMA table_info already lists).
ALTER TABLE c_allocationhdr ADD COLUMN c_currency_id;

-- 2026-10-10 (spec §57, F16): Fact.balanceAccounting needs C_AcctSchema_GL.UseCurrencyBalancing; the captured allocation headers need their C_Currency_ID (values from the SQLite seed).
ALTER TABLE c_acctschema_gl ADD COLUMN usecurrencybalancing;
UPDATE c_acctschema_gl SET usecurrencybalancing='Y' WHERE c_acctschema_id=101;
UPDATE c_acctschema_gl SET usecurrencybalancing='Y' WHERE c_acctschema_id=200000;
UPDATE c_allocationhdr SET c_currency_id=100 WHERE c_allocationhdr_id=100 AND c_currency_id IS NULL;
UPDATE c_allocationhdr SET c_currency_id=100 WHERE c_allocationhdr_id=101 AND c_currency_id IS NULL;

-- 2026-10-10 (spec §59): M_Warehouse_Acct (Inventory Differences account per warehouse/schema) — Doc_Inventory credits it; values from the SQLite seed.
CREATE TABLE IF NOT EXISTS m_warehouse_acct(m_warehouse_id INT, c_acctschema_id INT, w_differences_acct INT);
-- 2026-10-10 (spec §65.1, F24): MCost.setWeightedAverage rounds to 2 × the schema currency COSTING precision (MAcctSchema.getCostingPrecision = C_Currency.CostingPrecision,
-- MAcctSchema.java:550-570); Doc_MatchPO rounds the converted PO cost to it. Values from the SQLite seed ad_seed_fullwidth.db (USD 4, EUR 4). Guarded ALTER (loader skips an existing column).
ALTER TABLE c_currency ADD COLUMN costingprecision;
UPDATE c_currency SET costingprecision=4 WHERE c_currency_id IN (100,102,114) AND costingprecision IS NULL;
UPDATE c_currency SET costingprecision=0 WHERE c_currency_id=113 AND costingprecision IS NULL;
-- 2026-10-10 (spec §65.1, F24): Doc_InOut / Doc_MatchPO read the order line's TAX (rate, summary) to decide the purchase-cost tax correction (Doc_InOut.java:719-783);
-- the posting db has no c_tax. Rows = the SQLite seed ad_seed_fullwidth.db, client 11 (SQLite's own dictionary), not invented.
CREATE TABLE IF NOT EXISTS c_tax(c_tax_id INT, rate REAL, issummary TEXT, parent_tax_id INT);
-- 2026-10-10 (spec §66.2, F30): Doc_Cash / MCash read the cash line's type, invoice and currency and the cash book currency; the posting db's c_cashline / c_cashbook lack them.
-- Guarded ALTERs; cash book currencies from the SQLite seed ad_seed_fullwidth.db (101/102 → USD 100).
ALTER TABLE c_cashline ADD COLUMN cashtype;
ALTER TABLE c_cashline ADD COLUMN c_invoice_id;
ALTER TABLE c_cashline ADD COLUMN c_currency_id;
ALTER TABLE c_cashline ADD COLUMN c_charge_id;
ALTER TABLE c_cashline ADD COLUMN c_bankaccount_id;
ALTER TABLE c_cashbook ADD COLUMN c_currency_id;
UPDATE c_cashbook SET c_currency_id=100 WHERE c_cashbook_id IN (101,102) AND c_currency_id IS NULL;
-- 2026-10-10 (spec §66.2, F30): Doc.post → Fact.balanceSource books an unbalanced source on C_AcctSchema_GL.SuspenseBalancing_Acct when UseSuspenseBalancing='Y'; values from the SQLite seed.
ALTER TABLE c_acctschema_gl ADD COLUMN usesuspensebalancing;
ALTER TABLE c_acctschema_gl ADD COLUMN suspensebalancing_acct;
UPDATE c_acctschema_gl SET usesuspensebalancing='Y', suspensebalancing_acct=219 WHERE c_acctschema_id=101 AND usesuspensebalancing IS NULL;
UPDATE c_acctschema_gl SET usesuspensebalancing='Y', suspensebalancing_acct=200019 WHERE c_acctschema_id=200000 AND usesuspensebalancing IS NULL;
-- 2026-10-10 (spec §68, F32): Doc_AllocationHdr.balanceAccounting books the accounted difference of a foreign-currency allocation on C_AcctSchema_Default.RealizedLoss/Gain_Acct
-- (Doc_AllocationHdr.java:1807-1828); the posting db's c_acctschema_default lacks them. Guarded ALTERs; values from the SQLite seed ad_seed_fullwidth.db (= pilot).
ALTER TABLE c_acctschema_default ADD COLUMN realizedgain_acct;
ALTER TABLE c_acctschema_default ADD COLUMN realizedloss_acct;
UPDATE c_acctschema_default SET realizedgain_acct=245, realizedloss_acct=246 WHERE c_acctschema_id=101 AND realizedgain_acct IS NULL;
UPDATE c_acctschema_default SET realizedgain_acct=200027, realizedloss_acct=200028 WHERE c_acctschema_id=200000 AND realizedgain_acct IS NULL;
-- 2026-10-10 (spec §71, F35): Doc_ProjectIssue / MProjectIssue read the issue, its project (category, balance) and the project accounts; the posting db has none of them.
-- Tables created with the columns the fold reads; project + project-account rows from the SQLite seed ad_seed_fullwidth.db (client 11), not invented. Idempotent; never deletes.
CREATE TABLE IF NOT EXISTS c_projectissue(c_projectissue_id INT, ad_client_id INT, ad_org_id INT, c_project_id INT, line INT, m_product_id INT, m_locator_id INT, movementqty TEXT, movementdate TEXT, m_inoutline_id INT, s_timeexpenseline_id INT, docstatus TEXT);
CREATE TABLE IF NOT EXISTS c_project(c_project_id INT, ad_client_id INT, ad_org_id INT, projectcategory TEXT, projectbalanceamt TEXT);
CREATE TABLE IF NOT EXISTS c_project_acct(c_project_id INT, c_acctschema_id INT, pj_wip_acct INT, pj_asset_acct INT);
